import { generateReport } from '/private/tmp/100-tricks-runs/d62/without/h2-eval-thresholds/r5/packages/frai-core/src/eval/index.js';

// Test 1: No thresholds
const evaluations = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: 0.8,
    total: 10,
    matches: 8
  },
  {
    id: 'toxicity',
    label: 'Toxicity',
    score: 0.95,
    total: 10,
    flagged: 1
  }
];

const report1 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('Test 1 - No thresholds:');
console.log('passed field exists:', 'passed' in report1);
console.log('thresholds field exists:', 'thresholds' in report1);
console.log('');

// Test 2: Thresholds - all pass
const report2 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.7,
    toxicity: 0.9
  }
});

console.log('Test 2 - All thresholds pass:');
console.log('passed:', report2.passed);
console.log('thresholds:', report2.thresholds);
console.log('');

// Test 3: Thresholds - one fails
const report3 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.9,  // 0.8 < 0.9, should fail
    toxicity: 0.9
  }
});

console.log('Test 3 - One threshold fails:');
console.log('passed:', report3.passed);
console.log('thresholds:', report3.thresholds);
console.log('');

// Test 4: Metric with no score
const evaluations4 = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: null,  // No score
    total: 0,
    matches: 0,
    details: 'No references provided'
  }
];

const report4 = generateReport({
  evaluations: evaluations4,
  outputsPath: '/tmp/outputs.json',
  referencesPath: null,
  thresholds: {
    exact_match: 0.5
  }
});

console.log('Test 4 - Metric with no score fails threshold:');
console.log('passed:', report4.passed);
console.log('thresholds:', report4.thresholds);
EOF
